const UA='MSJ Student Investment Fund Research Desk (educational equity research)';
const memo=new Map();
const inFlight=new Map();
const metrics=['TotalRevenue','OperatingIncome','NetIncome','OperatingCashFlow','CapitalExpenditure','DilutedEPS','GrossProfit','DepreciationAndAmortization','CashCashEquivalentsAndShortTermInvestments','TotalDebt','DilutedAverageShares','StockholdersEquity','StockBasedCompensation','Receivables','Inventory','InterestExpense'];
function numeric(x){if(x===null||x===undefined||x==='')return null;const n=Number(x);return Number.isFinite(n)?n:null}
async function getJSON(url,ttl=60){const now=Date.now(),cached=memo.get(url);if(cached&&now-cached.time<ttl*1000)return cached.value;if(ttl>0&&inFlight.has(url))return inFlight.get(url);const task=(async()=>{const r=await fetch(url,{headers:{'User-Agent':UA,Accept:'application/json'},signal:AbortSignal.timeout(14000)});if(!r.ok)throw new Error('Provider returned '+r.status);const value=await r.json();value.__compoundFetchedAt=new Date(now).toISOString();if(memo.size>250)memo.delete(memo.keys().next().value);memo.set(url,{time:now,value});return value})();if(ttl>0)inFlight.set(url,task);try{return await task}finally{if(inFlight.get(url)===task)inFlight.delete(url)}}
async function yahoo(path,ttl){try{return await getJSON('https://query2.finance.yahoo.com/'+path,ttl)}catch{return await getJSON('https://query1.finance.yahoo.com/'+path,ttl)}}
function normalizeChart(data){const r=data?.chart?.result?.[0];if(!r?.meta||!Number.isFinite(r.meta.regularMarketPrice))throw Error('Quote unavailable');const m=r.meta,q=r.indicators?.quote?.[0];return{symbol:m.symbol,name:m.longName||m.shortName||m.symbol,currency:m.currency,exchange:m.fullExchangeName||m.exchangeName,price:m.regularMarketPrice,previousClose:numeric(m.previousClose)??(r.timestamp?.length>1?numeric(q?.close?.at(-2)):numeric(m.chartPreviousClose)),marketTime:m.regularMarketTime?new Date(m.regularMarketTime*1000).toISOString():null,high52:numeric(m.fiftyTwoWeekHigh),low52:numeric(m.fiftyTwoWeekLow),history:(r.timestamp||[]).map((t,i)=>({date:new Date(t*1000).toISOString().slice(0,10),close:numeric(q?.close?.[i])})).filter(p=>p.close!==null),source:'Yahoo Finance',retrievedAt:data.__compoundFetchedAt||new Date().toISOString()}}
async function quote(symbol,history=false,fresh=false){return normalizeChart(await yahoo('v8/finance/chart/'+encodeURIComponent(symbol)+'?interval=1d&range='+(history?'1y':'1d'),fresh?0:60))}
function normalizeFundamentals(data){const results=data?.timeseries?.result||[],series={};let currencies=new Set();for(const r of results){let key=r.meta?.type?.[0];if(!key)continue;series[key.replace('quarterly','')]=(r[key]||[]).filter(p=>p.periodType==='3M'&&Number.isFinite(p.reportedValue?.raw)).map(p=>{if(p.currencyCode)currencies.add(p.currencyCode);return{date:p.asOfDate,value:p.reportedValue.raw}}).sort((a,b)=>a.date.localeCompare(b.date))}
if(currencies.size&&(!currencies.has('USD')||[...currencies].some(c=>c!=='USD')))throw Error('Only USD financial statements supported');const revenues=series.TotalRevenue||[];if(!revenues.length)throw Error('No reported quarterly financials');const dates=revenues.slice(-4).map(r=>r.date);const complete=dates.length===4&&dates.every((d,i)=>i===0||(Date.parse(d)-Date.parse(dates[i-1]))/86400000<125&&(Date.parse(d)-Date.parse(dates[i-1]))/86400000>60);
const at=(key,date)=>series[key]?.find(p=>p.date===date)?.value??null;const sum=(key)=>{const vals=dates.map(d=>at(key,d));return complete&&vals.every(v=>v!==null)?vals.reduce((a,b)=>a+b,0):null};const latest=key=>series[key]?.at(-1)||null;
const annual={revenue:sum('TotalRevenue'),operatingIncome:sum('OperatingIncome'),netIncome:sum('NetIncome'),cfo:sum('OperatingCashFlow'),capex:sum('CapitalExpenditure'),da:sum('DepreciationAndAmortization'),grossProfit:sum('GrossProfit'),stockComp:sum('StockBasedCompensation'),interest:sum('InterestExpense')};if(annual.capex!==null)annual.capex=Math.abs(annual.capex);annual.fcf=annual.cfo!==null&&annual.capex!==null?annual.cfo-annual.capex:null;annual.ebitda=annual.operatingIncome!==null&&annual.da!==null?annual.operatingIncome+annual.da:null;
const yearGrowth=key=>{const rows=series[key]||[],last=rows.at(-1);if(['Receivables','Inventory'].includes(key)&&last?.date!==revenues.at(-1)?.date)return null;const old=last&&rows.find(p=>Math.abs((Date.parse(last.date)-Date.parse(p.date))/86400000-365)<20);return old?.value>0?last.value/old.value-1:null};
const balance={cash:latest('CashCashEquivalentsAndShortTermInvestments'),debt:latest('TotalDebt'),shares:latest('DilutedAverageShares'),equity:latest('StockholdersEquity')};const end=revenues.at(-1),prior=revenues.find(p=>Math.abs((Date.parse(end.date)-Date.parse(p.date))/86400000-365)<20);let invested=[];for(const date of [prior?.date,end.date]){const debt=at('TotalDebt',date),equity=at('StockholdersEquity',date),cash=at('CashCashEquivalentsAndShortTermInvestments',date);if([debt,equity,cash].every(v=>v!==null))invested.push(debt+equity-cash)}
return{source:'Yahoo Finance standardized quarterly statements',retrievedAt:data.__compoundFetchedAt||new Date().toISOString(),asOf:end.date,currency:'USD',annual,balances:balance,quarters:revenues.map(r=>{const cfo=at('OperatingCashFlow',r.date),capex=at('CapitalExpenditure',r.date);return{date:r.date,revenue:r.value,operatingIncome:at('OperatingIncome',r.date),grossProfit:at('GrossProfit',r.date),netIncome:at('NetIncome',r.date),eps:at('DilutedEPS',r.date),capex:capex===null?null:Math.abs(capex),fcf:cfo!==null&&capex!==null?cfo-Math.abs(capex):null}}),yoyGrowth:prior&&prior.value>0?end.value/prior.value-1:null,operatingMargin:annual.revenue>0&&annual.operatingIncome!==null?annual.operatingIncome/annual.revenue:null,fcfMargin:annual.revenue>0&&annual.fcf!==null?annual.fcf/annual.revenue:null,roic:invested.length===2&&(invested[0]+invested[1])>0&&annual.operatingIncome!==null?annual.operatingIncome*.79/((invested[0]+invested[1])/2):null,forensics:{cashConversion:annual.netIncome>0&&annual.cfo!==null?annual.cfo/annual.netIncome:null,capexIntensity:annual.revenue>0&&annual.capex!==null?annual.capex/annual.revenue:null,shareGrowth:yearGrowth('DilutedAverageShares'),receivablesGrowth:yearGrowth('Receivables'),inventoryGrowth:yearGrowth('Inventory'),stockCompRatio:annual.revenue>0&&annual.stockComp!==null?annual.stockComp/annual.revenue:null,interestCoverage:annual.interest>0&&annual.operatingIncome!==null?annual.operatingIncome/annual.interest:null,operatingMarginChange:prior&&at('OperatingIncome',prior.date)!==null&&at('OperatingIncome',end.date)!==null?at('OperatingIncome',end.date)/end.value-at('OperatingIncome',prior.date)/prior.value:null,grossMarginChange:prior&&at('GrossProfit',prior.date)!==null&&at('GrossProfit',end.date)!==null?at('GrossProfit',end.date)/end.value-at('GrossProfit',prior.date)/prior.value:null},roicDefinition:'Proxy: TTM operating income × 79% / average year-ago and latest quarter equity + debt − cash. Not company-reported ROIC.'}}
async function fundamentals(symbol,fresh=false){const now=Math.floor(Date.now()/1000);let path='ws/fundamentals-timeseries/v1/finance/timeseries/'+encodeURIComponent(symbol)+'?type='+metrics.map(m=>'quarterly'+m).join(',')+'&period1='+(now-86400*900)+'&period2='+(now+86400);return normalizeFundamentals(await yahoo(path,fresh?0:21600))}
async function nasdaq(path,ttl){const d=await getJSON('https://api.nasdaq.com/api/'+path,ttl);if(!d.data)throw Error('No provider coverage');return {...d.data,__compoundFetchedAt:d.__compoundFetchedAt}}
async function analyst(symbol){const results=await Promise.allSettled([nasdaq('analyst/'+symbol+'/targetprice',3600),nasdaq('analyst/'+symbol+'/earnings-forecast',21600)]);let target=results[0].status==='fulfilled'?results[0].value:null,earnings=results[1].status==='fulfilled'?results[1].value:null;let c=target?.consensusOverview,h=target?.historicalConsensus?.at(-1);const map=rows=>(rows||[]).map(r=>({period:r.fiscalEnd,eps:numeric(r.consensusEPSForecast),high:numeric(r.highEPSForecast),low:numeric(r.lowEPSForecast),count:numeric(r.noOfEstimates),up:numeric(r.up),down:numeric(r.down)}));const annual=map(earnings?.yearlyForecast?.rows),quarterly=map(earnings?.quarterlyForecast?.rows);if(!c&&!annual.length&&!quarterly.length)throw Error('Analyst coverage unavailable');return{source:'Nasdaq analyst consensus',retrievedAt:target?.__compoundFetchedAt||earnings?.__compoundFetchedAt,targetRetrievedAt:target?.__compoundFetchedAt||null,estimatesRetrievedAt:earnings?.__compoundFetchedAt||null,asOf:h?.z?.date||null,estimatesAsOf:earnings?.yearlyForecast?.asOf||null,target:c?{mean:numeric(c.priceTarget),low:numeric(c.lowPriceTarget),high:numeric(c.highPriceTarget),buy:numeric(c.buy),hold:numeric(c.hold),sell:numeric(c.sell)}:null,annual,quarterly,growthProxy:annual.length>1&&annual[0].eps>0&&annual[1].eps!==null?annual[1].eps/annual[0].eps-1:null}}
async function profile(symbol){const d=await nasdaq('quote/'+symbol+'/summary?assetclass=stocks',21600);return{sector:d.summaryData?.Sector?.value||null,industry:d.summaryData?.Industry?.value||null}}
async function company(symbol){const tasks={quote:()=>quote(symbol,true),financials:()=>fundamentals(symbol),analysts:()=>analyst(symbol),profile:()=>profile(symbol)};let result={symbol,fetchedAt:new Date().toISOString(),errors:{}};await Promise.all(Object.entries(tasks).map(async([key,fn])=>{try{result[key]=await fn()}catch(e){result[key]=null;result.errors[key]=e.message}}));return result}
async function search(q,fresh=false){const d=await yahoo('v1/finance/search?q='+encodeURIComponent(q)+'&quotesCount=12&newsCount=0',fresh?0:600);return(d.quotes||[]).filter(r=>r.quoteType==='EQUITY'&&/^[A-Z0-9.-]{1,16}$/.test(r.symbol)).map(r=>({symbol:r.symbol,name:r.longname||r.shortname||r.symbol,exchange:r.exchDisp,industry:r.industryDisp||null}))}
async function research(symbol,fresh=false){const result={symbol,retrievedAt:new Date().toISOString(),news:[],filings:[],errors:{}};await Promise.all([ (async()=>{try{const d=await yahoo('v1/finance/search?q='+encodeURIComponent(symbol)+'&quotesCount=0&newsCount=10',fresh?0:900);result.news=(d.news||[]).filter(n=>n.relatedTickers?.includes(symbol)&&/^https:\/\//.test(n.link||'')).slice(0,6).map(n=>({title:n.title,publisher:n.publisher,url:n.link,publishedAt:n.providerPublishTime?new Date(n.providerPublishTime*1000).toISOString():null}));result.newsRetrievedAt=d.__compoundFetchedAt}catch(e){result.errors.news=e.message}})(),(async()=>{try{let cikValue=typeof TICKER_CIK!=='undefined'?(TICKER_CIK[symbol]||TICKER_CIK[symbol.replace('.','-')]):null;if(!cikValue){const tickers=await getJSON('https://www.sec.gov/files/company_tickers.json',fresh?0:86400);cikValue=Object.values(tickers).find(t=>t?.ticker?.replace('-','.')===symbol.replace('-','.'))?.cik_str}if(!cikValue)throw Error('SEC ticker mapping unavailable');const cik=String(cikValue).padStart(10,'0');const d=await getJSON('https://data.sec.gov/submissions/CIK'+cik+'.json',fresh?0:3600);let r=d.filings?.recent;if(!r)throw Error('No recent filings returned');result.filings=r.form.map((form,i)=>({form,date:r.filingDate[i],reportDate:r.reportDate?.[i],accession:r.accessionNumber[i],document:r.primaryDocument[i]})).filter(f=>['10-K','10-Q','20-F','6-K','8-K','10-K/A','20-F/A'].includes(f.form)&&f.document&&f.accession).slice(0,8).map(f=>({form:f.form,date:f.date,reportDate:f.reportDate,url:'https://www.sec.gov/Archives/edgar/data/'+Number(cik)+'/'+f.accession.replaceAll('-','')+'/'+f.document}));result.filingsRetrievedAt=d.__compoundFetchedAt;result.filingsSource='SEC EDGAR'}catch(e){try{const d=await nasdaq('company/'+symbol+'/sec-filings?limit=40&sortColumn=filed&sortOrder=desc&isQuoteMedia=true',fresh?0:3600);let rows=(d.rows||[]).filter(f=>['10-K','10-Q','20-F','6-K','8-K','10-K/A','20-F/A'].includes(f.formType)).map(f=>({form:f.formType,date:f.filed,reportDate:f.period,url:f.view?.htmlLink}));for(const f of d.latest||[]){if(f.value&&!rows.some(r=>r.url===f.value)){const u=new URL(f.value);rows.push({form:f.label,date:u.searchParams.get('dateFiled'),reportDate:null,url:f.value})}}result.filings=rows.filter(f=>f.url?.startsWith('https://app.quotemedia.com/')).slice(0,8);if(!result.filings.length)throw Error('No mirrored filing links');result.filingsRetrievedAt=d.__compoundFetchedAt;result.filingsSource='Nasdaq / QuoteMedia mirror of SEC filings'}catch{result.errors.filings=e.message}}})()]);return result}
async function checkFeeds(symbol){const start=Date.now(),checks=[];let researchPromise;const run=async(key,fn)=>{const t=Date.now();try{const result=await fn();checks.push({key,status:result.available?'ok':'empty',checkedAt:new Date().toISOString(),durationMs:Date.now()-t,...result})}catch(e){checks.push({key,status:/No provider coverage|No reported quarterly|Only USD financial|Quote unavailable|SEC ticker mapping unavailable/.test(e.message||'')?'empty':'error',available:false,checkedAt:new Date().toISOString(),durationMs:Date.now()-t,message:e.message||'Request failed'})}};await Promise.all([
run('quotes',async()=>{const q=await quote(symbol,true,true);return{available:true,retrievedAt:q.retrievedAt,sourceTime:q.marketTime,message:'New upstream quote/history request succeeded. Price '+q.price+' '+q.currency+'; '+q.history.length+' daily-close observations. An older trade timestamp can reflect a closed market or delayed quote.'}}),
run('financials',async()=>{const f=await fundamentals(symbol,true);return{available:true,retrievedAt:f.retrievedAt,sourceTime:f.asOf,message:f.annual.revenue!==null?'Quarterly statements returned; four aligned quarters available for TTM revenue.':'Quarterly statements returned; TTM coverage is incomplete.'}}),
run('targets',async()=>{const d=await nasdaq('analyst/'+symbol+'/targetprice',0),a=d.consensusOverview;return{available:typeof a?.priceTarget==='number',retrievedAt:d.__compoundFetchedAt,sourceTime:d.historicalConsensus?.at(-1)?.z?.date||null,message:a?'Target data returned. Consensus date is provider-supplied and may precede retrieval.':'Provider responded without a price target for this company.'}}),
run('earnings',async()=>{const d=await nasdaq('analyst/'+symbol+'/earnings-forecast',0),a=d.yearlyForecast;return{available:!!a?.rows?.length,retrievedAt:d.__compoundFetchedAt,sourceTime:a?.asOf||null,message:a?.rows?.length?'Annual forecast rows returned for '+a.rows.map(r=>r.fiscalEnd).slice(0,2).join(' and ')+'.':'Provider responded without annual EPS estimates.'}}),
run('search',async()=>{const results=await search(symbol,true);return{available:results.some(r=>r.symbol===symbol),retrievedAt:new Date().toISOString(),sourceTime:null,message:results.length?'Equity search returned '+results.length+' matches.':'Search responded without an equity match.'}}),
run('filings',async()=>{researchPromise||=research(symbol,true);const r=await researchPromise;if(r.errors.filings)throw Error(r.errors.filings);return{available:!!r.filings.length,retrievedAt:r.filingsRetrievedAt,sourceTime:r.filings[0]?.date||null,message:r.filingsSource||'No recent filings returned.'}}),
run('news',async()=>{researchPromise||=research(symbol,true);const r=await researchPromise;if(r.errors.news)throw Error(r.errors.news);return{available:!!r.news.length,retrievedAt:r.newsRetrievedAt,sourceTime:r.news[0]?.publishedAt||null,message:r.news.length?r.news.length+' company-tagged headlines returned.':'Provider responded with no company-tagged headlines; this is not proof that no relevant news exists.'}})
]);return{symbol,checkedAt:new Date().toISOString(),durationMs:Date.now()-start,cacheBypassed:true,checks}}

const CREST="";
const FEED_STATUS="export const feedDefinitions=[\n{key:'quotes',name:'Quote & price history',provider:'Yahoo Finance',description:'Latest provider price; historical daily closes.'},\n{key:'financials',name:'Quarterly financial statements',provider:'Yahoo Finance',description:'Provider-standardized reported financials; not a separate live accounting feed.'},\n{key:'targets',name:'Analyst price targets',provider:'Nasdaq',description:'Consensus target, range and analyst rating counts.'},\n{key:'earnings',name:'Analyst EPS forecasts',provider:'Nasdaq',description:'Annual EPS estimates and revision counts.'},\n{key:'search',name:'Company search',provider:'Yahoo Finance',description:'Equity ticker and company-name lookup.'},\n{key:'filings',name:'Company filings',provider:'SEC EDGAR / Nasdaq–QuoteMedia',description:'Direct submissions or attributed document mirrors.'},\n{key:'news',name:'Company-related news',provider:'Yahoo Finance / named publishers',description:'Provider-tagged company coverage; empty results do not prove there is no news.'}\n];\nexport function classifyFeed({available=false,error=null,checked=false,retrievedAt=null,sourceTime=null,stale=false,empty=false,message=''}){if(stale&&available)return{state:'stale',label:'Stale snapshot',tone:'warn',retrievedAt,sourceTime,message:message||'Stored data is displayed after a failed refresh.'};if(error)return{state:'error',label:'Request failed',tone:'bad',retrievedAt,sourceTime,message:String(error)};if(available)return{state:'ok',label:checked?'Responding':'Loaded',tone:'good',retrievedAt,sourceTime,message};if(checked||empty)return{state:'empty',label:'No coverage',tone:'warn',retrievedAt,sourceTime,message:message||'Request succeeded, but this company has no usable result for this feed.'};return{state:'unknown',label:'Not checked',tone:'neutral',retrievedAt,sourceTime,message:message||'No completed request for this feed in this session.'}}\nexport function observedFeeds(company=null,research=null,searchResult=null){const c=company||{},q=c.quote,f=c.financials,a=c.analysts,r=research;const snapshot=c.snapshotStale===true;return feedDefinitions.map(def=>{let input={};switch(def.key){case'quotes':input={available:typeof q?.price==='number',error:!q?c.errors?.quote:null,stale:!!c.stale,retrievedAt:q?.retrievedAt,sourceTime:q?.marketTime,message:'Source time is the provider trade timestamp. Market closure or delays can make it older than retrieval.'};break;case'financials':input={available:!!f?.asOf,error:c.errors?.financials,stale:snapshot,retrievedAt:f?.retrievedAt,sourceTime:f?.asOf,message:'Latest financial period. TTM totals require four aligned reported quarters.'};break;case'targets':input={available:typeof a?.target?.mean==='number',error:!a?c.errors?.analysts:null,empty:!!a,stale:snapshot,retrievedAt:a?.targetRetrievedAt,sourceTime:a?.asOf,message:a?.target?'Consensus period may be older than its retrieval time.':'No price target returned; EPS coverage can still be available.'};break;case'earnings':input={available:!!a?.annual?.length,error:!a?c.errors?.analysts:null,empty:!!a,stale:snapshot,retrievedAt:a?.estimatesRetrievedAt,sourceTime:a?.estimatesAsOf,message:a?.annual?.length?'Forecast periods: '+a.annual.slice(0,2).map(e=>e.period).join(' → ')+'. Provider as-of may be missing.':'No annual EPS forecast returned for this company.'};break;case'search':input=searchResult||{};break;case'filings':input={available:!!r?.filings?.length,error:r?.errors?.filings,empty:!!r,retrievedAt:r?.filingsRetrievedAt,sourceTime:r?.filings?.[0]?.date,message:r?.filingsSource||'Filing feed has not loaded for this company.'};break;case'news':input={available:!!r?.news?.length,error:r?.errors?.news,empty:!!r,retrievedAt:r?.newsRetrievedAt,sourceTime:r?.news?.[0]?.publishedAt,message:r?.news?.length?'Publication time shown for the first returned article.':'No company-tagged headlines returned, or this feed has not been loaded.'};break}return{...def,...classifyFeed(input)}})}\nexport function summarizeFeeds(rows){const failed=rows.filter(r=>r.state==='error').length,unknown=rows.filter(r=>r.state==='unknown').length,stale=rows.filter(r=>r.state==='stale').length,empty=rows.filter(r=>r.state==='empty').length,ok=rows.filter(r=>r.state==='ok').length;return{failed,unknown,stale,empty,ok,total:rows.length,tone:failed&&ok===0?'bad':failed||stale||empty?'warn':unknown?'neutral':'good',label:failed?'Some requests failed':stale?'Stale data is displayed':empty?'Some company coverage is missing':unknown?'Some feeds not checked':'All checked feeds returned data'}}\n";
